	router.POST(options.BaseURL+"/admin/coaches/:id/audit", wrapper.PostAdminCoachesIdAudit)
	router.GET(options.BaseURL+"/admin/metrics/overview", wrapper.GetAdminMetricsOverview)
	router.GET(options.BaseURL+"/admin/moderation/tasks", wrapper.GetAdminModerationTasks)
	router.POST(options.BaseURL+"/admin/moderation/tasks/:id/resolve", wrapper.PostAdminModerationTasksIdResolve)
	router.GET(options.BaseURL+"/admin/reports", wrapper.GetAdminReports)
	router.POST(options.BaseURL+"/admin/reports/:id/resolve", wrapper.PostAdminReportsIdResolve)
	router.POST(options.BaseURL+"/ai/analyze", wrapper.PostAiAnalyze)
	router.POST(options.BaseURL+"/ai/chat", wrapper.PostAiChat)
	router.POST(options.BaseURL+"/ai/interpret", wrapper.PostAiInterpret)
	router.GET(options.BaseURL+"/ai/quota", wrapper.GetAiQuota)
	router.GET(options.BaseURL+"/appointments", wrapper.GetAppointments)
	router.POST(options.BaseURL+"/appointments", wrapper.PostAppointments)
	router.GET(options.BaseURL+"/appointments/:id", wrapper.GetAppointmentsId)
